/* 2D Grid Dashboard Layout */
.dashboard-grid {
  display: grid;
  grid-template-columns: 260px 1fr;
  grid-template-rows: 60px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar content";
  min-height: 100vh;
}

/* 1D Flexbox Navigation Bar */
.nav-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Specificity Score: 0-1-0 */
.button {
  background-color: blue;
}

/* Specificity Score: 1-1-0 (Wins over .button) */
#main-content .button {
  background-color: purple;
}

/* Always set explicit aspect ratios or width/height */
img {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9; /* Prevents layout jump before load */
}

/* Reserve placeholder space for dynamic components */
.skeleton-loader {
  min-height: 200px;
}
